package ma.projet.service; import ma.projet.beans.*; import ma.projet.util.HibernateUtil; import org.hibernate.Session; import java.time.LocalDate; import java.util.*; public class HommeService extends GenericService<Homme>{public HommeService(){super(Homme.class);} public List<Mariage> epousesEntre(Long id,LocalDate a,LocalDate b){try(Session s=HibernateUtil.getSessionFactory().openSession()){return s.createQuery("from Mariage m join fetch m.femme where m.homme.id=:id and m.dateDebut between :a and :b",Mariage.class).setParameter("id",id).setParameter("a",a).setParameter("b",b).list();}} public List<Mariage> details(Long id){return epousesEntre(id,LocalDate.of(1,1,1),LocalDate.of(9999,12,31));} }
